 // High wall monitors leave a full standing body and all enemy silhouettes clear.
 for(const floor of [3.6,0])for(const f of walls){if(monitorFloors.get(floor)>=3)break;const y=floor+2.10,points=[];for(let i=0;i<f.vertices.length;i++){const a=f.vertices[i],b=f.vertices[(i+1)%f.vertices.length];if((a[1]-y)*(b[1]-y)>=0||Math.abs(a[1]-b[1])<.001)continue;const t=(y-a[1])/(b[1]-a[1]);points.push(new THREE.Vector3(a[0]+(b[0]-a[0])*t,y,a[2]+(b[2]-a[2])*t))}if(points.length<2||points[0].distanceTo(points[1])<3)continue;const center=points[0].clone().add(points[1]).multiplyScalar(.5),n=new THREE.Vector3(...f.normal);if(center.x<map.bounds.minX||center.x>map.bounds.maxX||center.z<map.bounds.minZ||center.z>map.bounds.maxZ||(center.x>2&&center.x<5&&center.z>4&&center.z<13)||(center.x>-3&&center.x<3&&center.z<-15))continue;const front=center.clone().addScaledVector(n,1);if(!data.nav.nodes.some(p=>Math.abs(p.y-floor)<.3&&Math.hypot(p.x-front.x,p.z-front.z)<.7))continue;if(props.some(p=>p.userData.dressing?.role==='wall-equipment'&&p.position.distanceTo(center)<6))continue;const location=center.clone().addScaledVector(n,.30),object=place('waste-tv',location.x,y,location.z,{height:.34,rotation:Math.atan2(n.x,n.z),sourceEntityId:f.entityId,role:'wall-equipment'});if(object){object.userData.dressing.sourceFaceId=f.id;monitorFloors.set(floor,monitorFloors.get(floor)+1);const mount=center.clone().addScaledVector(n,.07);detail(cube,housing,mount,[.18,.10,.18])}}
